
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_edf2_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_edf2", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.697447836085529e+00, -3.627155842626385e+00, -3.528691696096419e+00, -3.392360701543000e+00, -3.206729899246155e+00, -2.959952289531878e+00, -2.642894730976900e+00, -2.254732223209222e+00, -1.810354188863928e+00, -1.344632573216276e+00, -9.058708432771213e-01, -6.294658666765383e-01, -5.454828092940247e-01, -4.515556755292180e-01, -3.260244849410460e-01, -2.030238116059365e-01, -1.141351740710104e-01, -6.535150341172569e-02, -3.706460031010095e-02, -2.396856429528892e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


